#include <bits/stdc++.h>
using namespace std;struct P{char l;string r;};
int main(){int n;if(!(cin>>n))return 0;vector<P> ps;set<char> nts,ts;string line;for(int i=0;i<n;i++){cin>>line;auto k=line.find("->");if(k==string::npos)return 1;char l=line[0];nts.insert(l);stringstream ss(line.substr(k+2));string x;while(getline(ss,x,'|'))ps.push_back({l,x});}char start;string input;cin>>start>>input;for(auto&p:ps)for(char c:p.r)if(c!='#'&&!isupper((unsigned char)c))ts.insert(c);ts.insert('$');
 map<char,set<char>> F,Follow;auto fs=[&](string s){set<char> z;bool nul=true;for(char c:s){if(c=='#')continue;if(!nts.count(c)){z.insert(c);nul=false;break;}for(char t:F[c])if(t!='#')z.insert(t);if(!F[c].count('#')){nul=false;break;}}if(nul)z.insert('#');return z;};bool ch=true;while(ch){ch=false;for(auto&p:ps){auto z=fs(p.r);auto old=F[p.l].size();F[p.l].insert(z.begin(),z.end());ch|=old!=F[p.l].size();}}Follow[start].insert('$');ch=true;while(ch){ch=false;for(auto&p:ps)for(int i=0;i<(int)p.r.size();i++)if(nts.count(p.r[i])){auto z=fs(p.r.substr(i+1));auto old=Follow[p.r[i]].size();for(char c:z)if(c!='#')Follow[p.r[i]].insert(c);if(z.count('#'))Follow[p.r[i]].insert(Follow[p.l].begin(),Follow[p.l].end());ch|=old!=Follow[p.r[i]].size();}}
 map<pair<char,char>,int> table;bool conflict=false;for(int i=0;i<(int)ps.size();i++){auto z=fs(ps[i].r);for(char t:z)if(t!='#'){auto key=make_pair(ps[i].l,t);if(table.count(key)){cout<<"LL(1) conflict at ["<<ps[i].l<<","<<t<<"]\n";conflict=true;}else table[key]=i;}if(z.count('#'))for(char t:Follow[ps[i].l]){auto key=make_pair(ps[i].l,t);if(table.count(key)){cout<<"LL(1) conflict at ["<<ps[i].l<<","<<t<<"]\n";conflict=true;}else table[key]=i;}}
 cout<<"Parsing table entries:\n";for(auto &[k,v]:table)cout<<k.first<<","<<k.second<<" : "<<k.first<<"->"<<ps[v].r<<'\n';if(conflict){cout<<"Grammar is not LL(1); parse skipped.\n";return 0;}
 input+='$';vector<char> st={'$',start};size_t ip=0;cout<<"\nStack/Input trace:\n";while(!st.empty()){char top=st.back(),look=input[ip];if(top=='$'&&look=='$'){cout<<"Accepted\n";return 0;}if(top==look){st.pop_back();++ip;continue;}if(!nts.count(top)){cout<<"Rejected: terminal mismatch\n";return 0;}auto it=table.find({top,look});if(it==table.end()){cout<<"Rejected: no table entry for "<<top<<","<<look<<'\n';return 0;}st.pop_back();string r=ps[it->second].r;if(r!="#")for(auto q=r.rbegin();q!=r.rend();++q)st.push_back(*q);}
 cout<<"Rejected\n";
}
